import Foundation

/// Original, bundled role-play scenes and example replies; no network is required.
struct ConversationTopic {
    struct Lines {
        let opening: String
        let example: String
        let followUp: String
        let secondExample: String
        let closing: String
    }
    let id: String
    let situation: String
    let direction: String
    let keywords: [String]
    let italian: Lines
    let spanish: Lines
    let french: Lines
    let portuguese: Lines

    func lines(for language: LanguageCode) -> Lines? {
        switch language.rawValue {
        case "it": return italian
        case "es", "es-419": return spanish
        case "fr": return french
        case "pt", "pt-BR": return portuguese
        default: return nil
        }
    }

